<?php
namespace App\Http\Controllers;
use App\Models\{TicketBatch,RaffleSetting}; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;
class TicketController extends Controller { public function design(){return view('tickets.design',['setting'=>RaffleSetting::firstOrCreate(['id'=>1],['store_name'=>'Portátiles Perú','minimum_purchase'=>50,'prize'=>'Canasta navideña','draw_date'=>now()->setDate(2026,12,24)])]);} public function create(){return view('tickets.create',['setting'=>RaffleSetting::firstOrCreate(['id'=>1],['store_name'=>'Portátiles Perú','minimum_purchase'=>50,'prize'=>'Canasta navideña','draw_date'=>now()->setDate(2026,12,24)])]);} public function store(Request $r){$data=$r->validate(['quantity'=>'required|integer|min:1|max:10000','per_sheet'=>'required|integer|in:1,2,4','start_number'=>'nullable|integer|min:1|max:99999999']); $data['start_number']??=((int)TicketBatch::max('end_number'))+1; $data['end_number']=$data['start_number']+$data['quantity']-1; $batch=DB::transaction(fn()=>TicketBatch::create($data+['user_id'=>$r->user()->id])); return redirect()->route('tickets.history')->with('success',"Se generaron {$batch->quantity} tickets correctamente.");} public function history(){return view('history.index',['batches'=>TicketBatch::with('user')->latest()->paginate(15)]);} }
